R=/scratch/jjyeung/orch_n30
date -u +%TZ
mkdir -p $R/sb_kbox3/prompts $R/sb_kbox3/out
echo  | base64 -d > $R/sb_kbox3/prompts/sb_kbox3.md
echo sb_kbox3 >> $R/sb_queue/queue.txt
mkdir -p $R/sb_rlrev2; cp $R/sb_cursor_probe/AGENTS.md $R/sb_rlrev2/AGENTS.md
echo  | base64 -d > $R/sb_rlrev2/PROMPT.md
cd $R/sb_rlrev2 && tmux new-session -d -s sb_rlrev2 "OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 nice -n 10 timeout 7200 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes, completely.' > cursor.log 2>&1"
sleep 25; tail -1 $R/sb_queue/codexq.log; tmux ls -F "#{session_name}" | grep "^sb_" | tr "\n" " "
